import pyomo.environ as pyo

DATA = {
    "foods": ["milk", "vegetables"],
    "nutrients": ["calcium", "iron"],
    "cost": {"milk": 1, "vegetables": 2},
    "nutrient_content": {
        "calcium": {"milk": 40, "vegetables": 15},
        "iron": {"milk": 25, "vegetables": 30},
    },
    "nutrient_requirement": {"calcium": 100, "iron": 50},
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Sets
    model.FOODS = pyo.Set(initialize=d["foods"])
    model.NUTRIENTS = pyo.Set(initialize=d["nutrients"])

    # Decision variables: whole servings of each food
    model.servings = pyo.Var(
        model.FOODS, within=pyo.NonNegativeIntegers, bounds=(0, None)
    )

    # Objective: minimize total cost
    def obj_rule(m):
        return sum(d["cost"][f] * m.servings[f] for f in m.FOODS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Constraint: meet minimum requirement for each nutrient
    def nutrient_rule(m, n):
        return sum(
            d["nutrient_content"][n][f] * m.servings[f] for f in m.FOODS
        ) >= d["nutrient_requirement"][n]

    model.nutrient_requirement = pyo.Constraint(
        model.NUTRIENTS, rule=nutrient_rule
    )

    return model


